{"tool":"write","path":"tests/test_export_csv.py","content":"import unittest

from reports.export import export_csv


class TestExportCsv(unittest.TestCase):
    def test_header_and_rows_crlf(self):
        out = export_csv([{"a": 1, "b": 2}, {"a": 3, "b": 4}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n1,2\r\n3,4\r\n")

    def test_quoting_and_doubling(self):
        out = export_csv([{"x": 'he said "hi"', "y": "a,b", "z": "p\r\nq"}], ["x", "y", "z"])
        self.assertEqual(out, 'x,y,z\r\n"he said ""hi""","a,b","p\r\nq"\r\n')

    def test_missing_and_none_are_empty(self):
        out = export_csv([{"a": None}, {"b": 5}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n,\r\n,5\r\n")

    def test_values_str_nonstring(self):
        out = export_csv([{"a": 1.5, "b": True}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n1.5,True\r\n")

    def test_unselected_fields_ignored(self):
        out = export_csv([{"a": 1, "zzz": 9}], ["a"])
        self.assertEqual(out, "a\r\n1\r\n")

    def test_empty_rows_gives_header_only(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}, {"b": 2}], []), "")
        self.assertEqual(export_csv([], []), "")

    def test_one_shot_generators(self):
        rows = ({"a": i, "b": i * 2} for i in range(3))
        cols = (c for c in ["a", "b"])
        out = export_csv(rows, cols)
        self.assertEqual(out, "a,b\r\n0,0\r\n1,2\r\n2,4\r\n")

    def test_unicode_preserved(self):
        out = export_csv([{"a": "caf\u00e9 \u4e2d\u6587"}], ["a"])
        self.assertEqual(out, "a\r\ncaf\u00e9 \u4e2d\u6587\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        for bad in ([1, "a"], [None], [("a",)]):
            with self.assertRaises(ValueError):
                export_csv([], bad)

    def test_inputs_not_mutated(self):
        rows = [{"a": 1, "b": 2}]
        cols = ["a", "b"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(cols, ["a", "b"])

    def test_custom_mapping_missing_get(self):
        class MinimalMapping:
            def __init__(self, data):
                self._data = data

            def get(self, key, default=""):
                return self._data.get(key, default)

        out = export_csv([MinimalMapping({"a": 7})], ["a", "b"])
        self.assertEqual(out, "a,b\r\n7,\r\n")


if __name__ == "__main__":
    unittest.main()
